from .repository import contact_exists, put_contact


def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)


def import_contacts(connection, rows):
    try:
        rows = iter(rows)
    except TypeError as error:
        raise ValueError("Contacts must be an iterable of rows") from error

    contacts = []
    emails = set()
    for row in rows:
        if not isinstance(row, dict) or set(row) != {"email", "name"}:
            raise ValueError("Each contact must have exactly email and name")
        if not isinstance(row["email"], str) or not isinstance(row["name"], str):
            raise ValueError("Email and name must be strings")
        email = row["email"].strip().lower()
        name = row["name"].strip()
        if (email.count("@") != 1 or email.startswith("@")
                or email.endswith("@") or any(char.isspace() for char in email)):
            raise ValueError("Invalid email")
        if not name:
            raise ValueError("Name must not be empty")
        if email in emails:
            raise ValueError("Duplicate email in batch")
        emails.add(email)
        contacts.append((email, name))

    summary = {"inserted": 0, "updated": 0}
    if not contacts:
        return summary

    with connection:
        # Explicitly begin so the entire batch is atomic even in autocommit mode.
        connection.execute("BEGIN")
        for email, name in contacts:
            key = "updated" if contact_exists(connection, email) else "inserted"
            put_contact(connection, email, name)
            summary[key] += 1
    return summary
def initialize(connection):
    connection.execute("CREATE TABLE contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL)")
    connection.commit()

def list_contacts(connection):
    return connection.execute("SELECT email, name FROM contacts ORDER BY email").fetchall()

def put_contact(connection, email, name):
    connection.execute("INSERT INTO contacts VALUES (?, ?) ON CONFLICT(email) DO UPDATE SET name=excluded.name", (email, name))


def contact_exists(connection, email):
    return connection.execute(
        "SELECT 1 FROM contacts WHERE email = ?", (email,)
    ).fetchone() is not None
from .service import add_contact, import_contacts

def handle_add(connection, payload):
    add_contact(connection, payload["email"], payload["name"])
    return {"ok": True}

def handle_import(connection, payload):
    if (not isinstance(payload, dict) or set(payload) != {"contacts"}
            or not isinstance(payload["contacts"], list)):
        raise ValueError("Payload must contain only a contacts list")
    return import_contacts(connection, payload["contacts"])
